const results = [];

// ============================================================
// 🔒 SAFE HELPERS (Defined once outside the loop)
// ============================================================
function getParam(node, paramName) {
  if (!node || !Array.isArray(node.elementParameter)) return null;
  const param = node.elementParameter.find(p => p && p.name === paramName);
  if (!param || param.value === undefined || param.value === null) return null;
  return String(param.value).replace(/^"|"$/g, '');
}

function findDynamicParam(node, possibleNames) {
  if (!node || !Array.isArray(node.elementParameter)) return null;
  for (const name of possibleNames) {
    const param = node.elementParameter.find(p => p && p.name && p.name.toUpperCase() === name.toUpperCase());
    if (param && param.value !== undefined && param.value !== null && String(param.value).trim() !== "") {
      return String(param.value).replace(/^"|"$/g, '');
    }
  }
  return null;
}

function cleanFileName(rawName) {
  if (!rawName || rawName === "N/A") return "N/A";
  let cleaned = String(rawName).replace(/^"|"$/g, '');
  const fileMatch = cleaned.match(/["']?([a-zA-Z0-9_\-]+\.(csv|xlsx|xml|json|txt|dat|zip|gz))["']?/i);
  if (fileMatch) return fileMatch[1];
  if (cleaned.includes("globalMap") || cleaned.includes("context.") || cleaned.includes("row")) {
    return "(dynamic filename)";
  }
  const pathParts = cleaned.split(/[\\/]/);
  if (pathParts.length > 1) return pathParts[pathParts.length - 1];
  return cleaned;
}

function getGDriveProp(node, propName) {
  if (!node || !Array.isArray(node.elementParameter)) return null;
  const propParam = node.elementParameter.find(p => p && p.name === "PROPERTIES");
  if (!propParam || !propParam.value) return null;
  let props = propParam.value;
  if (typeof props === 'string') {
    try { props = JSON.parse(props); } catch(e) { return null; }
  }
  const prop = props[propName];
  if (!prop) return null;
  let val = prop.storedValue !== undefined ? prop.storedValue : prop;
  if (val === null || val === undefined) return null;
  if (typeof val === 'object' && val.name !== undefined) return val.name;
  if (typeof val === 'object' && val.value !== undefined) return val.value;
  if (typeof val === 'string') return val.replace(/^"|"$/g, '').replace(/\\"/g, '"');
  return val;
}

function getNodeLabel(node) {
  if (!node || !Array.isArray(node.elementParameter)) return null;
  const labelParam = node.elementParameter.find(p => p && p.name === "LABEL");
  if (!labelParam || !labelParam.value) return null;

  let labelValue = String(labelParam.value);
  const brMatch = labelValue.match(/<br\s*\/?>(.+)/i);
  if (brMatch && brMatch[1]) {
    return brMatch[1].trim();
  }
  return labelValue.replace(/<[^>]*>/g, '').trim();
}

function classifyComponent(compName) {
  const name = compName.toLowerCase();
  if (/db|mysql|postgresql|oracle|mssql|sqlserver|jdbc|snowflake|synapse|bigquery|redshift|sqlite|mariadb|cassandra|mongodb|db2|teradata/.test(name)) return 'SQL';
  if (/salesforce/i.test(name)) return '';
  if (/rest|soap|http|webservice|api|graphql|twitter|slack|telegram|jira|confluence|github|trello|sendgrid|twilio/.test(name)) return 'API';
  if (/file|ftp|sftp|s3|google|drive|dropbox|onedrive|box|local|csv|excel|xml|json|parquet|avro|sharepoint|azure|blob/.test(name)) {
    const isOutput = /output|put|create|write|insert|update|delete|send|upload|bulk/.test(name);
    const isInput = /input|list|get|read|fetch|retrieve|extract|download/.test(name);
    if (isOutput && !isInput) return 'FILE_OUTPUT';
    return 'FILE_INPUT'; 
  }
  if (/output|put|create|write|send|upload/.test(name)) return 'GENERIC_OUTPUT';
  if (/input|list|get|read|fetch/.test(name)) return 'GENERIC_INPUT';
  return 'OTHER';
}

// ============================================================
// 🔄 PROCESS EACH INPUT ITEM
// ============================================================
for (const item of $input.all()) {
  const rawInput = item.json;
  const unwrapped = Array.isArray(rawInput) ? rawInput[0] : rawInput;
  const processType = unwrapped && unwrapped["talendfile:ProcessType"]
    ? unwrapped["talendfile:ProcessType"] : unwrapped;

  if (!processType) {
    results.push({ json: { _debug: "ProcessType not found", keys: Object.keys(unwrapped || {}) } });
    continue;
  }

  // 1. Get the filepath or filename from the input
  const rawPath = rawInput.filePath || rawInput.fileName || rawInput.name || "";

  // We trust that jobName is always provided from the previous nodes
  let extractedJobName = rawInput.jobName || "Unknown_Job";
  let talendVersion = rawInput.tmcVersion || rawInput.talendVersion || "0.1.0";

  if (rawPath && rawPath.trim() !== "") {
    const fileNameWithExt = rawPath.includes("/") ? rawPath.split("/").pop() : rawPath;
    let cleanName = fileNameWithExt.replace(/\.[^/.]+$/, "");
    cleanName = cleanName.replace(/_\d{6}-\d{6}$/, "");
    const nameFromPath = cleanName.replace(/_\d+(?:\.\d+)*$/, "");

    if (nameFromPath && nameFromPath.trim() !== "") {
      extractedJobName = nameFromPath;
    }

    if (!talendVersion || talendVersion === "0.0.0") {
      const versionMatch = cleanName.match(/_(\d+(?:\.\d+)+)$/);
      if (versionMatch) {
        talendVersion = versionMatch[1];
      }
    }
  } else if (processType.name) {
    const xmlName = processType.name;
    const cleanXmlName = xmlName.replace(/_\d{6}-\d{6}$/, "").replace(/_\d+(?:\.\d+)*$/, "");
    if (cleanXmlName && cleanXmlName.trim() !== "") {
      extractedJobName = cleanXmlName;
    }
  }

  const allNodes = Array.isArray(processType.node) ? processType.node : [];
  const rawConnections = Array.isArray(processType.connection) ? processType.connection : [];

  // ============================================================
  // 📥 INPUT & 📤 OUTPUT FILES
  // ============================================================
  const inputFiles = [];
  const outputFiles = [];

  for (const node of allNodes) {
    const comp = node?.componentName || "";
    const type = classifyComponent(comp);

    if (type === 'FILE_INPUT' || type === 'GENERIC_INPUT') {
      const rawFileName = findDynamicParam(node, ["FILENAME", "FILE", "PATH", "FOLDER", "DESTINATIONFOLDER", "BUCKET", "OBJECT", "URI", "URL"]) || "N/A";
      const folderPath = findDynamicParam(node, ["FILEPATH", "DIRECTORY", "FOLDER", "PATH", "BUCKETNAME", "CONTAINER"]) || "N/A";
      const encoding = findDynamicParam(node, ["ENCODING", "CHARSET"]) || "UTF-8";
      const format = findDynamicParam(node, ["FORMAT", "TYPE", "EXTENSION"]) || comp;

      let finalFileName = cleanFileName(rawFileName);
      let finalFolderPath = folderPath;
      if (finalFileName === "N/A" || finalFileName === "(dynamic filename)") {
        const gDriveFolder = getGDriveProp(node, "folder") || getGDriveProp(node, "destinationFolder");
        if (gDriveFolder) {
          finalFileName = `Folder: ${gDriveFolder}`;
          finalFolderPath = gDriveFolder;
        }
      }

      inputFiles.push({ 
        parameter: getParam(node, "UNIQUE_NAME") || comp, 
        fileName: finalFileName, 
        format: format, 
        mo: "M", 
        encoding: encoding, 
        folderPath: finalFolderPath, 
        fileExample: "" 
      });
    } 
    else if (type === 'FILE_OUTPUT' || type === 'GENERIC_OUTPUT') {
      const rawFileName = findDynamicParam(node, ["FILENAME", "FILE", "PATH", "FOLDER", "DESTINATIONFOLDER", "BUCKET", "OBJECT", "URI", "URL"]) || "N/A";
      const folderPath = findDynamicParam(node, ["FILEPATH", "DIRECTORY", "FOLDER", "PATH", "BUCKETNAME", "CONTAINER"]) || "N/A";
      const encoding = findDynamicParam(node, ["ENCODING", "CHARSET"]) || "UTF-8";
      const format = findDynamicParam(node, ["FORMAT", "TYPE", "EXTENSION"]) || comp;

      let finalFileName = cleanFileName(rawFileName);
      let finalFolderPath = folderPath;
      if (finalFileName === "N/A" || finalFileName === "(dynamic filename)") {
        const gDriveFolder = getGDriveProp(node, "folder") || getGDriveProp(node, "destinationFolder") || getGDriveProp(node, "newFolder");
        if (gDriveFolder) {
          finalFileName = `Upload to: ${gDriveFolder}`;
          finalFolderPath = gDriveFolder;
        }
      }

      outputFiles.push({ 
        parameter: getParam(node, "UNIQUE_NAME") || comp, 
        fileName: finalFileName, 
        format: format, 
        mo: "M", 
        encoding: encoding, 
        folderPath: finalFolderPath, 
        fileExample: "" 
      });
    }
  }

  // ============================================================
  // 🗄️ SQL & SOQL REQUESTS
  // ============================================================
  const sqlRequests = [];
  let sqlCounter = 1;
  let soqlCounter = 1;

  for (const node of allNodes) {
    const comp = node?.componentName || "";
    const type = classifyComponent(comp);
    const label = getNodeLabel(node) || getParam(node, "UNIQUE_NAME") || comp;

    if (type === 'SQL') {
      let sql = findDynamicParam(node, ["QUERY", "SQL_QUERY", "QUERYSTORE", "SELECT_QUERY", "INSERT_QUERY", "UPDATE_QUERY", "DELETE_QUERY"]);
      if (sql && sql.trim() !== "" && sql !== "N/A" && !sql.includes("QUERYSTORE_TYPE") && !sql.includes("[object Object]")) {
        sqlRequests.push({ id: `TSQL${sqlCounter++}`, description: label, sql: sql.trim() });
      }
    }
    else if (type === 'SOQL') {
      let soql = null;
      const propParam = node.elementParameter?.find(p => p && p.name === "PROPERTIES");
      if (propParam && propParam.value) {
        let props = propParam.value;
        if (typeof props === 'string') {
          try { props = JSON.parse(props); } catch(e) { props = null; }
        }
        if (props && typeof props === 'object') {
          let queryObj = props.query;
          if (typeof queryObj === 'object' && queryObj !== null) soql = queryObj.storedValue;
          else if (typeof queryObj === 'string') soql = queryObj;
        }
      }
      if (!soql && Array.isArray(node.elementParameter)) {
        for (const param of node.elementParameter) {
          let val = param.value;
          if (typeof val === 'object' && val !== null) val = val.storedValue;
          if (typeof val === 'string' && val.toUpperCase().includes("SELECT") && val.toUpperCase().includes("FROM")) {
            soql = val.replace(/^"|"$/g, '').trim();
            break;
          }
        }
      }
      if (soql && typeof soql === 'string' && soql.trim() !== "" && soql !== "N/A" && !soql.includes("QUERYSTORE_TYPE") && !soql.includes("@type") && !soql.includes("[object Object]")) {
        let section = "GENERAL";
        const labelLower = label.toLowerCase();
        if (labelLower.includes("invoice")) section = "INVOICE";
        else if (labelLower.includes("return") || labelLower.includes("credit")) section = "RETURN";
        else if (labelLower.includes("refund")) section = "REFUND";
        else if (labelLower.includes("payment")) section = "PAYMENT";
        else if (labelLower.includes("fulfillment")) section = "FULFILLMENT";
        sqlRequests.push({ id: `${section} SOQL${soqlCounter++}`, description: label, sql: soql.trim() });
      }
    }
  }

  // ============================================================
  // 🌐 API REQUESTS
  // ============================================================
  const apiRequests = [];
  for (const node of allNodes) {
    const comp = node?.componentName || "";
    const type = classifyComponent(comp);
    if (type === 'API') {
      const url = findDynamicParam(node, ["URI", "URL", "ENDPOINT", "SERVICE_URL", "WSDL", "HOST", "BASE_URL", "URI_SERVICE"]);
      const method = findDynamicParam(node, ["HTTP_METHOD", "METHOD", "VERB", "HTTP_VERB", "METHOD_HTTP"]) || "GET";
      let body = findDynamicParam(node, ["BODY", "PAYLOAD", "REQUEST_BODY", "SOAP_MESSAGE", "BODY_JSON", "REQUEST_BODY_JSON", "ENTITY_BODY", "CONTENT", "MESSAGE"]);

      if (!body) {
        const propParam = node.elementParameter?.find(p => p && p.name === "PROPERTIES");
        if (propParam && propParam.value) {
          let props = propParam.value;
          if (typeof props === 'string') { try { props = JSON.parse(props); } catch(e) { props = null; } }
          if (props) body = props.body || props.payload || props.requestBody || props.content || props.data || props.message || props.soapMessage || "";
        }
      }
      if (!body) {
        const bodyParam = node.elementParameter?.find(p => p && p.name && (p.name.toUpperCase().includes("BODY") || p.name.toUpperCase().includes("PAYLOAD") || (p.name.toUpperCase().includes("REQUEST") && p.name.toUpperCase().includes("BODY"))));
        if (bodyParam && bodyParam.value) body = String(bodyParam.value).replace(/^"|"$/g, '');
      }

      let headers = findDynamicParam(node, ["HEADERS", "HTTP_HEADERS", "HEADER", "CUSTOM_HEADERS"]);
      if (!headers || headers === "{}") {
        const propParam = node.elementParameter?.find(p => p && p.name === "PROPERTIES");
        if (propParam && propParam.value) {
          let props = propParam.value;
          if (typeof props === 'string') { try { props = JSON.parse(props); } catch(e) { props = null; } }
          if (props) headers = props.headers || props.httpHeaders || props.customHeaders || props.requestHeaders || "{}";
        }
      }
      if (!headers || headers === "{}") {
        const headerParam = node.elementParameter?.find(p => p && p.name && (p.name.toUpperCase().includes("HEADER") || p.name.toUpperCase().includes("HTTP_HEADER")));
        if (headerParam && headerParam.value) headers = String(headerParam.value).replace(/^"|"$/g, '');
      }

      let queryParams = findDynamicParam(node, ["QUERY_PARAMETERS", "QUERY_PARAMS", "PARAMS", "QUERY"]);
      if (!queryParams || queryParams === "{}") {
        const propParam = node.elementParameter?.find(p => p && p.name === "PROPERTIES");
        if (propParam && propParam.value) {
          let props = propParam.value;
          if (typeof props === 'string') { try { props = JSON.parse(props); } catch(e) { props = null; } }
          if (props) queryParams = props.queryParams || props.queryParameters || props.params || props.parameters || props.query || "{}";
        }
      }

      apiRequests.push({ requestName: getParam(node, "UNIQUE_NAME") || comp, method: method, url: url || "N/A", body: body || "", headers: headers || "{}", queryParams: queryParams || "{}" });
    }
  }

  // ============================================================
  // ️ MAPPING EXTRACTION
  // ============================================================
  const mappingTables = [];
  for (const node of allNodes) {
    const comp = node?.componentName || "";
    if (/tMap/i.test(comp)) {
      const mapName = getParam(node, "UNIQUE_NAME") || comp;
      const sourceConnections = rawConnections
        .filter(c => c.target === mapName && /MAIN|FLOW/i.test(c.connectorName || ""))
        .map(c => ({ source: c.source.replace(/_\d+$/, ""), connectorName: c.connectorName || "MAIN", label: getNodeLabel(allNodes.find(n => (n.componentName || "") === c.source.replace(/_\d+$/, ""))) }));

      const destinations = rawConnections
        .filter(c => c.source === mapName && /MAIN|FLOW/i.test(c.connectorName || ""))
        .map(c => c.target.replace(/_\d+$/, ""));

      let fieldMappings = [];
      const nodeData = node.nodeData;
      if (nodeData) {
        let outputTablesStr = nodeData.outputTables;
        let outputTables = null;
        if (typeof outputTablesStr === 'string') { try { outputTables = JSON.parse(outputTablesStr); } catch(e) {} }
        else if (typeof outputTablesStr === 'object') { outputTables = outputTablesStr; }

        if (outputTables) {
          const outputs = Array.isArray(outputTables) ? outputTables : [outputTables];
          for (const out of outputs) {
            const entries = out.mapperTableEntries;
            const tableEntries = Array.isArray(entries) ? entries : (entries ? [entries] : []);
            for (const entry of tableEntries) {
              const fieldName = entry.name || "";
              const fieldType = (entry.type || "").replace("id_", "");
              const expression = entry.expression || "Direct Mapping";
              let srcField = fieldName;
              let srcComp = sourceConnections[0]?.source || "Input";
              let srcLabel = sourceConnections[0]?.label;

              const rowMatch = String(expression).match(/(\w+)\.(\w+)/);
              if (rowMatch) {
                const rowVar = rowMatch[1];
                srcField = rowMatch[2];
                const connectorIndex = parseInt(rowVar.replace(/\D/g, '')) || 0;
                if (connectorIndex === 0) { srcComp = sourceConnections[0]?.source || "Input"; srcLabel = sourceConnections[0]?.label; } 
                else if (sourceConnections[connectorIndex]) { srcComp = sourceConnections[connectorIndex].source; srcLabel = sourceConnections[connectorIndex].label; }
              }
              const cleanSrcLabel = srcLabel ? String(srcLabel).trim() : "";
              const finalSrcComp = cleanSrcLabel ? `${srcComp}-${cleanSrcLabel}` : srcComp;
              fieldMappings.push({ srcComp: finalSrcComp, srcField: srcField, srcType: fieldType, destComp: destinations.join(", ") || "Output", destField: fieldName, destType: fieldType, rule: String(expression).replace(/\|/g, "\\|").replace(/\n/g, " ") });
            }
          }
        }
      }

      if (fieldMappings.length === 0) {
        const baseSrcComp = sourceConnections[0]?.source || "Input";
        const baseSrcLabel = sourceConnections[0]?.label;
        const cleanSrcLabel = baseSrcLabel ? String(baseSrcLabel).trim() : "";
        const finalSrcComp = cleanSrcLabel ? `${baseSrcComp}-${cleanSrcLabel}` : baseSrcComp;
        fieldMappings.push({ srcComp: finalSrcComp, srcField: "*", srcType: "-", destComp: destinations.join(", ") || "Output", destField: "*", destType: "-", rule: "See Talend Job (Expressions not extracted)" });
      }
      mappingTables.push({ mapName, rows: fieldMappings });
    }
  }

  // ============================================================
  // ⚙️ JOB PARAMS & INTRODUCTION
  // ============================================================
  const jobParams = [];
  const contexts = Array.isArray(processType.context) ? processType.context : [];
  const defaultContext = contexts.find(c => c.name === "Default") || contexts[0];
  const contextParams = Array.isArray(defaultContext?.contextParameter) ? defaultContext.contextParameter : [];

  for (const p of contextParams) {
    const val = p?.value || "";
    if (val.startsWith("enc:system.encryption") || val === "" || val === '""') continue;
    jobParams.push({ parameterName: p?.name || "Unknown", description: p?.comment || "", type: (p?.type || "id_String").replace("id_", ""), value: String(val).replace(/^"|"$/g, '') });
  }

  const hasInput = inputFiles.length > 0 || apiRequests.length > 0;
  const hasOutput = outputFiles.length > 0;
  const hasTransform = allNodes.some(n => /tMap|tAggregate|tFilter|tSort/i.test(n.componentName || ""));

  let introSentence = "This Talend job performs an integration task.";
  if (hasInput && hasOutput && hasTransform) introSentence = "This Talend job orchestrates data extraction from source systems, applies necessary transformations, and loads the processed data into target destinations.";
  else if (hasInput && hasOutput) introSentence = "This Talend job orchestrates data extraction from source systems and loads the processed data into target destinations.";
  else if (hasInput) introSentence = "This Talend job extracts data from source systems for processing.";
  else if (hasOutput) introSentence = "This Talend job loads data into target systems.";

  const introduction = { jobName: extractedJobName, author: processType.author || "N/A", creationDate: processType.creationDate || "N/A", purpose: introSentence };

  // ============================================================
  // 🔗 ENDPOINTS EXTRACTION
  // ============================================================
  const endpoints = [];
  for (const param of jobParams) {
    const name = param.parameterName.toLowerCase();
    if (name.includes("url") || name.includes("endpoint") || name.includes("host")) {
      let service = "Unknown", environment = "Unknown";
      if (name.includes("salesforce")) service = "Salesforce";
      else if (name.includes("synapse") || name.includes("azure")) service = "Azure Synapse";
      else if (name.includes("ftp")) service = "FTP";
      else if (name.includes("smtp") || name.includes("mail")) service = "SMTP";
      else if (name.includes("api")) service = "REST API";

      if (name.includes("dev") || name.includes("test")) environment = "Development";
      else if (name.includes("prod")) environment = "Production";
      else if (name.includes("int") || name.includes("integ")) environment = "Integration";
      else if (name.includes("loc")) environment = "Local";
      endpoints.push({ service, environment, port: "", url: param.value });
    }
  }

  const uniqueEndpoints = [];
  const seen = new Set();
  for (const ep of endpoints) {
    const key = `${ep.service}-${ep.url}`;
    if (!seen.has(key)) { seen.add(key); uniqueEndpoints.push(ep); }
  }

  // ============================================================
  // ✅ BUILD RESULT FOR THIS ITEM
  // ============================================================
  const isNewVersion = rawInput.isNewVersion !== false && String(rawInput.isNewVersion).toLowerCase() !== 'false';
  const commitMsg = rawInput.commitMsg || "";

  const result = { 
    introduction,
    JobName: extractedJobName,      
    talendVersion: talendVersion,            
    pageTitle: `${extractedJobName} - Integration Specification`, 
    isNewVersion,
    commitMsg,
    _debug: { rawFileName: rawPath, processTypeName: processType.name } 
  };
  if (inputFiles.length > 0) result.inputs = { file: inputFiles };
  if (outputFiles.length > 0) result.outputs = { file: outputFiles };
  if (sqlRequests.length > 0) result.sqlRequests = sqlRequests;
  if (apiRequests.length > 0) result.apiRequests = apiRequests;
  if (mappingTables.length > 0) result.mappings = mappingTables;
  if (jobParams.length > 0) result.jobParams = jobParams;
  if (uniqueEndpoints.length > 0) result.endpoints = uniqueEndpoints;
  if (rawConnections.length > 0) result.connections = rawConnections;
  if (allNodes.length > 0) result.nodes = allNodes.map(n => ({ uniqueName: getParam(n, "UNIQUE_NAME") || n.componentName, componentName: n.componentName || "" }));

  results.push({ json: result });
}

return results;

// 🔄 MODIFICATION MINIMALE: Process ALL jobs instead of just the first one
const results = [];

// Helper function to escape HTML
function escapeHtml(text) {
  if (text === null || text === undefined) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// NEW: Helper function to format and escape field values (handles strings, arrays, and objects)
function formatField(value) {
  if (value === null || value === undefined) return '';

  if (Array.isArray(value)) {
    return value.map(item => {
      if (typeof item === 'object' && item !== null) {
        // Format as key-value pairs if possible (e.g., { NAME: '...', VALUE: '...' } or { key: '...', value: '...' })
        const keys = Object.keys(item);
        if (keys.length >= 2) {
          return `<strong>${escapeHtml(String(item[keys[0]]))}</strong>: ${escapeHtml(String(item[keys[1]]))}`;
        }
        // Fallback for single key or other objects
        return escapeHtml(JSON.stringify(item));
      }
      return escapeHtml(String(item));
    }).join('<br/>');
  }

  if (typeof value === 'object') {
    return escapeHtml(JSON.stringify(value));
  }

  return escapeHtml(String(value));
}

// Helper to create HTML table with specific headers and row data mapping
function createTable(headers, rows, rowMapper) {
  let html = '<table class="wrapped" style="width:100%; border-collapse: collapse;">';
  html += '<thead><tr style="background-color: #f5f5f5;">';
  headers.forEach(h => {
    html += `<th style="padding: 8px; border: 1px solid #ddd; text-align: left;"><strong>${escapeHtml(h)}</strong></th>`;
  });
  html += '</tr></thead><tbody>';

  rows.forEach(row => {
    html += '<tr>';
    const cells = rowMapper(row);
    cells.forEach(cell => {
      // Added vertical-align: top for better rendering of multi-line content (like formatted headers/body)
      html += `<td style="padding: 8px; border: 1px solid #ddd; vertical-align: top;">${cell}</td>`; 
    });
    html += '</tr>';
  });

  html += '</tbody></table>';
  return html;
}

// 🔄 MODIFICATION MINIMALE: Loop through ALL jobs
for (const item of $input.all()) {
  const inputData = item.json;

  // 🌟 INTEGRATION: Generate the Mermaid Image URL directly here
  const mermaidCode = inputData.llmDiagram || "";
  let diagramImageUrl = inputData.diagramImageUrl || ""; // Fallback if already generated
  if (!diagramImageUrl && mermaidCode) {
    const base64Code = Buffer.from(mermaidCode)
      .toString('base64')
      .replace(/\+/g, '-')
      .replace(/\//g, '_')
      .replace(/=/g, '');
    diagramImageUrl = `https://mermaid.ink/img/${base64Code}`;
  }

  // Build HTML content
  let html = '';

  // Title with Status Macro
  html += '<h1>Integration Specification</h1>';
  html += '<ac:structured-macro ac:name="status" ac:schema-version="1">';
  html += '<ac:parameter ac:name="title">In progress</ac:parameter>';
  html += '<ac:parameter ac:name="colour">Yellow</ac:parameter>';
  html += '</ac:structured-macro>';
  html += '<p></p>';

  // 1. INTRODUCTION
  html += '<h2>Introduction</h2>';
  if (inputData.introduction && inputData.introduction.purpose) {
