// 🛡️ Helper: Compare semantic versions to find the highest one (e.g., "0.2" > "0.1")
function compareVersions(v1, v2) {
  const p1 = String(v1).split('.').map(Number);
  const p2 = String(v2).split('.').map(Number);
  for (let i = 0; i < 3; i++) {
    if ((p1[i] || 0) > (p2[i] || 0)) return 1;
    if ((p1[i] || 0) < (p2[i] || 0)) return -1;
  }
  return 0;
}

const jobsMap = {};

for (const commit of commits) {
  const allFiles = [...(commit.added || []), ...(commit.modified || [])];

  for (const filePath of allFiles) {
    const isProcessFile = filePath.includes('/process/') || filePath.startsWith('process/');
    if (!filePath.endsWith('.item') || !isProcessFile) continue;

    const fileName = filePath.split('/').pop();


    const match = fileName.match(/^(.+?)_(\d+(?:\.\d+)+)(?:_\d{6}-\d{6})?\.item$/i);

    let cleanName, talendVersion;
    if (match) {
      cleanName = match[1];       // Perfect job name without trailing underscores
      talendVersion = match[2];   // Exact version extracted
    } else {
      // Fallback for non-standard file names
      cleanName = fileName.replace(/\.item$/i, '');
      talendVersion = "0.0.0";
    }

    // 🔄 DEDUPLICATION: If multiple versions of the SAME job are pushed, keep ONLY the highest version
    if (jobsMap[cleanName]) {
      if (compareVersions(talendVersion, jobsMap[cleanName].talendVersion) > 0) {
        jobsMap[cleanName] = { filePath, branch, repoFullName, jobName: cleanName, talendVersion, commitMsg: commit.message };
      }
    } else {
      jobsMap[cleanName] = { filePath, branch, repoFullName, jobName: cleanName, commitMsg: commit.message };
    }
  }
}

// Return the clean, deduplicated list with the highest version for each job
return Object.values(jobsMap).map(data => ({ json: data }));

// 1. Get ALL items from the Merge node (which are now stacked together)
