// Bucket A: TMC API response 
// (We use a loop to collect all items just in case Merge5 passed duplicate TMC responses)
let tmcItems = [];
for (const item of allItems) {
  if (item.json.items && Array.isArray(item.json.items)) {
    tmcItems = tmcItems.concat(item.json.items);
  }
}

// Bucket B: Data Table rows (they have 'jobName' and 'talendVersion' but NO 'filePath' and NO 'items')
const dbItems = allItems.filter(item => item.json.jobName && !item.json.filePath && !item.json.items);

// Bucket C: The actual GitHub files we need to process (they are the ONLY ones with a 'filePath')
const changedFiles = allItems.filter(item => item.json.filePath);

// 🛡️ Helper: Clean job name to avoid trailing underscore mismatches (e.g. "job_" vs "job")
function cleanJobName(name) {
  if (!name) return "";
  return String(name).replace(/_+$/, '').trim();
}

// Semantic Versioning (SemVer) Comparison Helper
function compareVersions(v1, v2) {
  const p1 = String(v1).split('.').map(Number);
  const p2 = String(v2).split('.').map(Number);
  for (let i = 0; i < 3; i++) {
    if ((p1[i] || 0) > (p2[i] || 0)) return 1;
    if ((p1[i] || 0) < (p2[i] || 0)) return -1;
  }
  return 0;
}

const results = [];

// 3. Loop ONLY through the actual GitHub files (Bucket C)
for (const file of changedFiles) {
  const rawJobName = file.json.jobName;
  const cleanName = cleanJobName(rawJobName);

  // 4. Get TMC Version for this specific job (from Bucket A)
  let tmcVersion = "0.0.0";
  const tmcItem = tmcItems.find(item => cleanJobName(item.name) === cleanName);

  if (tmcItem && tmcItem.versions && tmcItem.versions.length > 0) {
    const rawVersion = tmcItem.versions[0]; // e.g., "0.1.1.20261108080920"
    const match = rawVersion.match(/^(\d+\.\d+\.\d+)/);
    tmcVersion = match ? match[1] : "0.0.0"; // Extracts "0.1.1"
  }

  // 5. Get Data Table Version for this specific job (from Bucket B)
  const dbRow = dbItems.find(item => cleanJobName(item.json.jobName) === cleanName);
  const dbVersion = dbRow ? (dbRow.json.talendVersion || "0.0.0") : "0.0.0";

  // 6. Compare versions and decide if we should process this job
  let isNewVersion = true; 

  if (tmcVersion === "0.0.0") {
    // Rule 1: Not deployed in TMC yet -> NEVER process
    isNewVersion = false;
  } 
  else if (compareVersions(tmcVersion, dbVersion) === 0) {
    // Rule 2: Versions are exactly the same -> Skip (Fixes the string vs number bug)
    isNewVersion = false;
  } 
  else if (dbRow) {
    // Rule 3: Job exists in DB -> Only process if TMC version is strictly higher
    isNewVersion = compareVersions(tmcVersion, dbVersion) > 0;
  } 
  else {
    // Rule 4: Job does NOT exist in DB, but IS deployed in TMC -> Process as brand new
    isNewVersion = true;
  }
  // 7. Push the clean, merged object for this job
  results.push({
    json: {
      filePath: file.json.filePath,
      branch: file.json.branch,
      repoFullName: file.json.repoFullName,
      jobName: cleanName, // Pass the cleaned name forward so downstream nodes match perfectly
      tmcVersion: tmcVersion,
      dbVersion: dbVersion,
      isNewVersion: isNewVersion,
      commitMsg: file.json.commitMsg || ""
    }
  });
}

// Return the list of processed jobs (handles 1 job or 100 jobs perfectly)
return results;

