  }

  const hasOpenThink = /<think>/i.test(raw);
  const hasCloseThink = /<\/think>/i.test(raw);

  let diagram = '';
  let diagramFailed = false;
  let diagramFailReason = '';

  if (hasOpenThink && !hasCloseThink) {
    // Reasoning never finished - the response was truncated mid-thought
    // (ran out of max_tokens before Qwen got to the actual answer). Anything
    // matching "sequenceDiagram" in here is just draft text from inside the
    // unfinished reasoning, not a real diagram, so don't try to salvage it.
    diagramFailed = true;
    diagramFailReason = 'Response truncated during reasoning (no closing </think> tag) - no diagram was produced.';
  } else {
    // Either there's no <think> block at all, or it's fully closed - safe
    // to strip it and only search the text that comes AFTER it.
    const afterThink = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
    const match = afterThink.match(/sequenceDiagram[\s\S]*/i);

    if (match) {
      diagram = match[0]
        .replace(/^```(?:mermaid)?\s*/i, '')
        .replace(/```\s*$/, '')
        .trim();
    } else {
      diagramFailed = true;
      diagramFailReason = 'No "sequenceDiagram" found in the model output after removing reasoning.';
    }
  }

  results.push({
    json: {
      llmDiagram: diagram,
      diagramFailed,
      diagramFailReason,
      // itemMatching (not .item) - guarantees the right job's name even if
      // the chain's batching returns results out of input order.
      JobName: jobName
    }
  });
